import React, { useRef, useEffect } from 'react';

// Pure gradient orb — no edges, dissolves into background
export default function MeshSphere({ size = 300, speed = 0.4, distort = 0.5, hue1 = 200, hue2 = 220 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2;

    const draw = () => {
      t.current += 0.004 * speed;
      ctx.clearRect(0, 0, size, size);
      const pulse = 1 + Math.sin(t.current * 0.5) * 0.028;
      const h1 = hue1 + Math.sin(t.current * 0.1) * 10;
      const h2 = hue2 + Math.cos(t.current * 0.08) * 8;
      const dx = Math.sin(t.current * 0.3) * size * 0.018;
      const dy = Math.cos(t.current * 0.24) * size * 0.014;

      // Outer corona
      const g1 = ctx.createRadialGradient(cx+dx, cy+dy, 0, cx, cy, size*0.50*pulse);
      g1.addColorStop(0,   `hsla(${h1+20}, 60%, 62%, 0.20)`);
      g1.addColorStop(0.4, `hsla(${h1},   56%, 54%, 0.12)`);
      g1.addColorStop(0.7, `hsla(${h2},   50%, 50%, 0.06)`);
      g1.addColorStop(1,   'transparent');
      ctx.fillStyle = g1; ctx.fillRect(0,0,size,size);

      // Core
      const g2 = ctx.createRadialGradient(cx+dx*0.5, cy+dy*0.5, 0, cx, cy, size*0.35*pulse);
      g2.addColorStop(0,    `hsla(${h1+25}, 65%, 68%, 0.90)`);
      g2.addColorStop(0.25, `hsla(${h1+10}, 62%, 58%, 0.78)`);
      g2.addColorStop(0.52, `hsla(${h1},    58%, 50%, 0.58)`);
      g2.addColorStop(0.78, `hsla(${h2},    52%, 46%, 0.28)`);
      g2.addColorStop(1,    'transparent');
      ctx.fillStyle = g2; ctx.fillRect(0,0,size,size);

      // Secondary blob
      const dx2=-Math.sin(t.current*0.22)*size*0.055, dy2=-Math.cos(t.current*0.18)*size*0.045;
      const g3 = ctx.createRadialGradient(cx+dx2, cy+dy2, 0, cx+dx2, cy+dy2, size*0.26*pulse);
      g3.addColorStop(0,   `hsla(${h2+8}, 60%, 60%, 0.65)`);
      g3.addColorStop(0.5, `hsla(${h2},   55%, 54%, 0.32)`);
      g3.addColorStop(1,   'transparent');
      ctx.fillStyle = g3; ctx.fillRect(0,0,size,size);

      // Hot centre
      const g4 = ctx.createRadialGradient(cx+dx*0.3, cy+dy*0.3, 0, cx, cy, size*0.13*pulse);
      g4.addColorStop(0,   `hsla(${h1+45}, 72%, 88%, 0.80)`);
      g4.addColorStop(0.45,`hsla(${h1+28}, 65%, 72%, 0.38)`);
      g4.addColorStop(1,   'transparent');
      ctx.fillStyle = g4; ctx.fillRect(0,0,size,size);

      raf.current = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort, hue1, hue2]);

  return <canvas ref={canvasRef} style={{ display:'block', width:`${size}px`, height:`${size}px` }} />;
}
